import re

# Strip the color sequences that hide text before a description is shown.
_COLOR = re.compile(r"\x1b\[[0-9;]*m")


def neutralize(text, placeholder="<ESC>"):
    """Return text that is safe to print in a terminal, marking every removed escape."""
    return _COLOR.sub(placeholder, text)

questions.solution:
def neutralize(text, placeholder="<ESC>"):
    """Return text that is safe to print in a terminal, marking every removed escape."""
    # Every escape sequence a modern terminal recognizes starts with byte 0x1b, so
    # replacing that one byte disarms them all; no sequence is allowed through.
    return text.replace("\x1b", placeholder)
